`||s.has(g)){p+=r;continue}if(r==="	"){p+=" ";continue}const b=r.normalize("NFD").replace(/[\u0300-\u036f]/g,"");p+=b&&[...b].every(S=>s.has(S.codePointAt(0)))?b:"?"}return p}}function lu(s,k,p,r){const g=[];for(const b of s.split(`
